        this.securityQuestion2 = q2;
        this.securityAnswer2 = hash.formula(Validator.normalizeAnswer(a2), answerSalt2);
        this.passwordSalt = hash.generateSalt();
        this.hashedPassword = hash.formula(password, passwordSalt);
    }

